grid2=[[1]*30 for _ in range(30)]
ys2=[1,9,17]; xs2=[1,10,20]
colors2=[[2,4,3],[3,6,9],[9,4,5]]
for i,y in enumerate(ys2):
  for j,x in enumerate(xs2):
    for r in range(y,y+6):
      for c in range(x,x+6): grid2[r][c]=8
    for r in range(y+2,y+4):
      for c in range(x+2,x+4): grid2[r][c]=colors2[i][j]
for c,v in zip([1,3,5,7,9,11,13,15,17],[2,4,3,9,5,4,6,3,9]): grid2[28][c]=v
# color only the background gaps between the 8-filled panels, in sequence order
# A->B, B->C
for r in range(3,5):
  for c in range(7,10): grid2[r][c]=2
  for c in range(16,20): grid2[r][c]=4
# C->F, F->I vertical
for c in range(22,24):
  for r in range(7,9): grid2[r][c]=3
  for r in range(15,17): grid2[r][c]=9
# I->H, H->E, E->D, D->G
for r in range(19,21):
  for c in range(16,20): grid2[r][c]=5
for c in range(12,14):
  for r in range(15,17): grid2[r][c]=4
for r in range(11,13):
  for c in range(7,10): grid2[r][c]=6
for c in range(3,5):
  for r in range(15,17): grid2[r][c]=3
assert len(grid2)==30 and all(len(r)==30 for r in grid2)
print('\n'.join(' '.join(map(str,row)) for row in grid2))
print('JSON:')
import json
print(json.dumps(grid2,separators=(',',':')))

